class Konto:
    def __init__(self, stand):
        self.stand = stand

    def einzahlen(self, betrag):
        self.stand += betrag
        return self.stand

    def abheben(self, betrag):
        if betrag > self.stand:
            return False
        self.stand -= betrag
        return True

