def fehlerstelle(text):
    paare = {')': '(', ']': '[', '}': '{'}
    offen = []
    for i, zeichen in enumerate(text):
        if zeichen in '([{':
            offen.append((zeichen, i))
        elif zeichen in paare:
            if not offen or offen[-1][0] != paare[zeichen]:
                return i
            offen.pop()
    if offen:
        return offen[0][1]
    return -1


def ausgeglichen(text):
    return fehlerstelle(text) == -1
